    {
        "zhuang": "Bouxdauh mwd fap.",
        "zh": "道公念符咒。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aiq ndaem lo, mwngz couh gvaq seiz.",
        "zh": "你要快些种啦，否则就过季节了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Loh myag lai.",
        "zh": "路太滑",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij haeux neix nienj ndaej naed raixcaix.",
        "zh": "这些米成粒的，碾得很好。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naj baengz naeg lai.",
        "zh": "布面很窄。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix naegnad lai.",
        "zh": "这个人太懒。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bonj saw neix naek lai lo.",
        "zh": "这本书太深奥了.",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Song boux de ganjcingz naekna lai.",
        "zh": "他们两人感情很深厚。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou ndaej bae Baekging naengh ndei lo.",
        "zh": "我能去北京就好了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Donq byaek haemhneix naengq raixcaix!",
        "zh": "今晚晚餐的菜很丰盛！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cenzsuijdingj naengz bongh youq laj raemx.",
        "zh": "潜水艇能在水底行驶。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naenx gij naeng duhnamh okbae.",
        "zh": "把花生皮捻出去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen mak neix naeuh lu.",
        "zh": "这个果子腐烂了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz naeuh lai lo.",
        "zh": "你太无能。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ngoenzneix de deng baihgwnz naeuz lo.",
        "zh": "今天他被上级责备了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naih ngeix naih siliengz.",
        "zh": "越想越凄凉。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Laj dat miz naj haz ndeu.",
        "zh": "山崖下有一片茅草。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Hwet de nanq raixcaix.",
        "zh": "他腰酸痛得很。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De daeuj gizneix ndaej haujlai nanz lo.",
        "zh": "他来这里很久了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cih saw neix nanzdauh mwngz mbouj rox ha?",
        "zh": "这个字难道你不认识吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De nanzmboujnanz daeuj baez ndeu.",
        "zh": "他久不久来一次。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaej nap naj gou.",
        "zh": "别捏我的脸。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De nauq youh daeuj?",
        "zh": "他为何又来？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nauz mwngz gag bae.",
        "zh": "不然你自己去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndaej mbaw geiznding ndeu.",
        "zh": "得一面红旗。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz bang gou ndaej lwi?",
        "zh": "你可以帮我吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj ndaej ndaekhix guh.",
        "zh": "不能这样做。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu raemx ndaengq daeuj saeg buh.",
        "zh": "要碱水来洗衣服。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij byaek neix ndaengq lai.",
        "zh": "这菜太咸了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ndaenj hwnj ci lo.",
        "zh": "他挤上车了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gwnzhaw vunz ndaet raixcaix.",
        "zh": "圩上人多，拥挤得很。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mou meh ndauq lo.",
        "zh": "母猪发情了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix caen ndeigyaez!",
        "zh": "这个人真可爱！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "⋯⋯ ndicih ciemz gyaj, ndicih ndaemnaz.",
        "zh": "要么就拔秧，要么就插秧。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aenvih de miz saehcingz, ndigah mbouj bae.",
        "zh": "因为他有事情，所以不去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ndiu lo.",
        "zh": "他醒了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gangj ndaej nduen lai hw.",
        "zh": "讲得很完满。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Go faex neix nduk lu.",
        "zh": "这颗树腐朽了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ne! Aen neix hawj mwngz!",
        "zh": "喏！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Miz mbouj miz ne?",
        "zh": "有没有呢？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaenx lumj meh de nei.",
        "zh": "象他母亲一样勤快。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ih maz neix?",
        "zh": "这个人为什么愁眉苦脸？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De neix mbouj youq ranz.",
        "zh": "他现在不在家。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De miz lwg nem mbouj ndaej bae lu.",
        "zh": "他有孩子牵挂，不能去了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij haeuxnaengj neix nembyadbyad.",
        "zh": "这些糯米饭粘粘的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij namh neix net leux lu.",
        "zh": "这些泥土变结实了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj ngaih saeh.",
        "zh": "不关事。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou mbouj ngaih mwngz saek di.",
        "zh": "我一点不妨碍你。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cehduh neix ok ngaz lo.",
        "zh": "这颗豆子发芽了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz gaej ngeiz de.",
        "zh": "你不要怀疑他。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ngoenzneix ngeuxgeuz mbouj gangj vah.",
        "zh": "他今天闹情绪;不讲话。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj ndaej ngoek gyaeuj lwgnyez.",
        "zh": "不能敲小孩的头.",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Fag cax neix ngoemx lo.",
        "zh": "这把刀钝了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Diuz loh neix ngutraurau.",
        "zh": "这条路弯弯曲曲的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nik aen bingj soiq bae.",
        "zh": "把这块饼压碎。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbwn nit lo.",
        "zh": "天冷了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij haeuxnaengj neix niu raixcaix.",
        "zh": "这些糯米饭很粘。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Duz ngwz nod bae.",
        "zh": "蛇爬走了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cingj mwngz noiz cienz hawj gou.",
        "zh": "请你暂借钱给我。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De nienzgeij lij nomj.",
        "zh": "他年纪还轻。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nu gij heiz gwnz ndang okdaeuj.",
        "zh": "把身上的污垢搓下来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij mba neix nuenx raixcaix.",
        "zh": "这些粉末很细。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nwi! Meh mwngz daeuj lu.",
        "zh": "唔！你的母亲来了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen loekci neix nwk lai.",
        "zh": "这个车轮很不润滑。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu baengz nwnh daeuj guh daejhaiz.",
        "zh": "拿碎布来做鞋底。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaiq reih neix nyaengq lo.",
        "zh": "这块畲地杂草丛生。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De cungj mbouj lau nyaenq.",
        "zh": "他总不害羞。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndaek haeuxsei neix nyaih lo.",
        "zh": "这块米花糖松散了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou mbouj aeu, de nyaiz hawj gou.",
        "zh": "我不要，他挜给我。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nyamx aen ceiz neix baenz song mbiengj bae.",
        "zh": "把这块糍巴夹成两半。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij ngaiz neix daiq nyan lai.",
        "zh": "这些饭太干了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaij nohvaiz neix nyangq lai.",
        "zh": "这块牛肉很韧。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij ngaiz neix cawj ndaej nyannyoeknyoek.",
        "zh": "这些饭煮得太干。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux mehmbwk neix nyanq lai.",
        "zh": "这个女人很泼辣。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gienh saeh neix ceiq miz nyawx.",
        "zh": "这件事最有意义。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Duz vaiz neik seiq nyaz lu.",
        "zh": "这头牛生四颗牙了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaej bae nyeh de.",
        "zh": "别理睬他。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj hawj de bae, de nyengh aeu bae.",
        "zh": "不让他去，他硬要去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix ndang nyieg lai.",
        "zh": "这个人身体很弱。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nyiengh de gangj gonq.",
        "zh": "让他先说。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz guh loek liux, de couh mbouj nyienghnaj.",
        "zh": "你做错了，他就不容情。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou gig nyienh'eiq bang de guh saeh.",
        "zh": "我很愿意帮他做点事。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou nyix de bae hagdangz.",
        "zh": "我以为他上学校去了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij byoem de nyoengqnywtnywt.",
        "zh": "他的头发蓬蓬松松的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Byoem gyaeuj de nyungqnyangq lai.",
        "zh": "他的头发很蓬乱。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Byoem gyaeuj de gig nyungqnyat.",
        "zh": "他的头发乱莲蓬的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "O! Gou rox lo.",
        "zh": "噢！我知道了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Yawj mbouj okda, duz moulwg neix miz cib gaen.",
        "zh": "看不出，这头小猪有十斤。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De gunghcoz guh ndaej oksaek.",
        "zh": "他工作做得出色。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ngoenzcog mwngz yaeng baema ong!",
        "zh": "明天你再回去吧！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Onggo! Yienghneix couh ndei lo.",
        "zh": "对！这样就好了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De youq raeb bya haenx aeu fwnz.",
        "zh": "他在山背后打柴。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raek lwgnyez bae guh hong.",
        "zh": "带着孩子去做工。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz gaej raemh gou.",
        "zh": "你别挡着我。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Miz ndit dak, raemxfwi cij ndaej swng hwnj mbwn.",
        "zh": "有太阳照射，水蒸气才会升上空中。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Guh saeh gaej raengrwz lai.",
        "zh": "做事别粗心大意。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Loh raeuz lai.",
        "zh": "路太滑。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Vaiz rag ci.",
        "zh": "牛拉车。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "⋯⋯ De rangh gangj rangh riu.",
        "zh": "他连讲带笑。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbanj neix miz haj ranz vunz.",
        "zh": "这个村子有五户人家。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij noh deng rumzbaek ci rengj liux lo!",
        "zh": "肉被北风吹干了！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Riengz henz dah byaij bae.",
        "zh": "沿着河边走。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raemxda rihnangnang.",
        "zh": "眼泪涔涔地流。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ringx bae ringx ma.",
        "zh": "滚来滚去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De riuhaha naeuz.",
        "zh": "他笑哈哈地说。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz gij saeh neix riuz okbae.",
        "zh": "把这件事情传出去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Vaiz roengz lwg.",
        "zh": "水牛生仔。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raemx roenx okdaeuj.",
        "zh": "水溢出来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz daeng daeuj rongh.",
        "zh": "拿灯来照亮。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbwn rongh lo, mbouj mizfwn lo.",
        "zh": "天晴了.不下雨了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ranz de youq lawz mwngz roxdingh lwi?",
        "zh": "他家在哪里你知道吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ngoenzneix co'ngeih roxnaeuz cosam?",
        "zh": "今天是初二还是初三？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz roxnaj de lwi?",
        "zh": "你认识他吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz gangj vah gou mbouj roxyiuj.",
        "zh": "你讲话我听不懂。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Caezgya rumj daeuj yawj.",
        "zh": "大家围拢来看。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Noh cawj dwk rwt liux lo.",
        "zh": "肉煮得收缩了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Sad gwn song gaen noh.",
        "zh": "居然吃了两斤肉。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj miz saek di.",
        "zh": "一点也没有。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Saek bak baj gaen.",
        "zh": "大约一百多斤。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Saeklaeuq de daeuj daengz mwngz baenzlawz guh ne?",
        "zh": "万一他来到，你怎么办呢？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndang saenz.",
        "zh": "身体发抖。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De maij caux saenzsied.",
        "zh": "他好拨弄是非。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen lwgndae neix saepsangsang, mbouj ndei gwn saek di.",
        "zh": "这个柿子涩的，一点也不好吃。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen lwgndae neix saepsatsat, mbouj ndei gwn saek di.",
        "zh": "这个柿子涩涩的，一点也不好吃。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raemx saepsonj.",
        "zh": "水下降。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Duz max neix sanggvanggyang.",
        "zh": "这匹马高高的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij sing de sangsatsat.",
        "zh": "他的声音很高。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen bya neix sangvidvid.",
        "zh": "这座山高高的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dizyinz daeuj saujdang.",
        "zh": "敌人来扫荡。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De sawqyupyup cungj mbouj gamj bae guh.",
        "zh": "他试了又试总不敢去做。",
        "source": "zhuang_dictionary"
    },
